function ActivityCrisisContractMain:WarmUp()
    if self._hasBeenWarmUp then return end
    if isNotNull(self._coWarmUp) then return end
    self._coWarmUp = cs_coroutine.start(function()
        for i = 1, 3, 1 do
            self.ChapterList:ExpandPool()
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.02))
        end
        self._hasBeenWarmUp = true
        self._coWarmUp = nil
    end)
end

function ActivityCrisisContractMain:AddUIClick()
    SetButtonAction(self.BtnShop.gameObject,Bind(self,self.OnBtnShopClick))
    SetButtonAction(self.BtnEntry.gameObject,Bind(self,self.OnBtnEntryClick))
    SetButtonAction(self.BtnRanking.gameObject,Bind(self,self.OnBtnRankingClick))
    SetButtonAction(self.BtnTask.gameObject,Bind(self,self.OnBtnTaskClick))
