function ActivityCrisisContractMain:OnTipsAction()
    ---@type ActivityCrisisUtils
    local vo = ActivityCrisisUtils.GetActivityVo(self.activityData.activityContentId)
    if isNotNull(vo) and isNotNull(vo.ruleID)then
        CfUtils.ShowModuleToast(vo.ruleID)
    end
end

function ActivityCrisisContractMain:OnInitialize()
    local activityData = ActivityCrisisUtils.GetActivityCrisisMgr():GetActivityData()
    self.activityData = activityData
    self:RefreshActivityTime()
    GameUtils.Request(Interfaces.ActivityStrangeTaleHome,{activityUuid = activityData.id },function(request,response)
        if checkInt(response.errCode) == 0 then
            ActivityCrisisUtils.GetActivityCrisisMgr():InitialDojo(response.data)
            local isPlayChapter = checkNumber(CfUtils.GetLocalData("ActivityCrisisContractMainChapter",0)) == 1
            if isPlayChapter then
                self:OnChapterEnd()
            else
                ChapterUtils.ProcessChapter(checkNumber(response.data.schedule.storyStartId), function(go)
                    self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
                    URPCameraController:SetMainCameraActive(false)
                    self._plotGo = go
                end, function()
                    self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
                    URPCameraController:SetMainCameraActive(true)
                    CfUtils.WriteLocalData("ActivityCrisisContractMainChapter",1)
                    self:OnChapterEnd()
                    CfUtils.SafeDelete(self._plotGo)
                end)
            end
        end
    end)
end

function ActivityCrisisContractMain:OnChapterEnd()
    local isNeedOpen = ActivityCrisisUtils.GetActivityCrisisMgr():IsNeedOpenTaskDialog()
    if isNeedOpen then
        local questId = ActivityCrisisUtils.GetActivityCrisisMgr():GetCompleteQuestId()
        self:OpenTaskDialog(questId)
        ActivityCrisisUtils.GetActivityCrisisMgr():UpdateNewCompleteTask(0)
        ActivityCrisisUtils.GetActivityCrisisMgr():UpdateCompleteQuestId(0)
    else
        self:RefreshUI()
    end
end

function ActivityCrisisContractMain:RefreshUI()
    local dojo = ActivityCrisisUtils.GetActivityCrisisMgr():GetActivityDojo()
    if not isNull(dojo) then
        self:RefreshNormalQuest(dojo)
        self:RefreshRotationQuest(dojo)
        self:RefreshRedPoint(dojo)
        self:PlayBgm(dojo)
        self:RefreshCurrency()
    end
end

function ActivityCrisisContractMain:RefreshCurrency()
    local vo = ActivityCrisisUtils.GetActivityVo(self.activityData.activityContentId)
    CfUtils.RefreshTopGoods({vo.storeCornId})
end

function ActivityCrisisContractMain:PlayBgm(dojo)
    local bgm = dojo.schedule.bgm
    if not isNull(bgm) then
        ---@type CriWareUtils
        local CriWareUtils    = import('Game.Entry.CriWareUtilsFix')
        CriWareUtils.PlayMusicById(bgm)
    end
end

function ActivityCrisisContractMain:RefreshActivityTime()
    --region 时间
    local startTime =  self.activityData.startTime
    local closeTime =  self.activityData.closeTime
    local ActivityUtils         = import("Game.Activity.ActivityUtils")
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
end

function ActivityCrisisContractMain:RefreshNormalQuest(dojo)
    local data = dojo:GetNormalQuestData()
    ---@type ActivityCrisisUtils
    local questVo = ActivityCrisisUtils.GetCrisisEventLevelVo(data.questId)
    CfUtils.FillText(self.TxtDesc,questVo.name)
    CfUtils.FillText(self.TxtNum,table.concat({data.receivedTaskNum,"/",data.taskNum}))
end

function ActivityCrisisContractMain:RefreshRedPoint(dojo)
    local isHave = dojo:IsHaveTaskRedPoint()
    local redGo = GameUtils.GetRedPointGo(self.BtnTask)
    if isNotNull(redGo) then
        CfUtils.SetActive(redGo.gameObject,isHave)
    end
end

function ActivityCrisisContractMain:RefreshRotationQuest(dojo)
    local data = dojo:GetRotationQuest()
    if  isNull(data) then
        return
    end
    self._data = data

    for i, v in pairs(self._data) do
        v.index = i
    end

    if self._coFillSelf then
        cs_coroutine.stop(self._coFillSelf)
        self._coFillSelf = nil
    end
    self._coFillSelf = cs_coroutine.start(function()
        if not self._hasBeenWarmUp then
            self:WarmUp()
        end
        while not isNull(self._coWarmUp) do
            cs_coroutine.yield_return(nil)
        end
        CfUtils.SetActive(self.ChapterList, false)
        self.ChapterList:InitListView(0, self._data)
        CfUtils.SetActive(self.ChapterList, true)
        self.ChapterList:InitListView(table.count(self._data), self._data)
        self.ChapterList.OnIndexChanged = Bind(self, self.OnSelectCell)
        self._coFillSelf = nil
    end)
end

function ActivityCrisisContractMain:OnSelectCell(index)
    local vo = self._data[index + 1]
    self._lastSelectId = vo.id
end

function ActivityCrisisContractMain:OnFinalize()

end

